update fin_sale_record
dept_id = #{deptId}, period_id = #{periodId}, sale_no = #{saleNo}, product_id = #{productId}, member_id = #{memberId}, member_no = #{memberNo}, member_name = #{memberName}, product_name = #{productName}, sale_quantity = #{saleQuantity}, gift_quantity = #{giftQuantity}, total_quantity = #{totalQuantity}, sale_amount = #{saleAmount}, unit_price = #{unitPrice}, paid_amount = #{paidAmount}, sale_date = #{saleDate}, status = #{status}, del_flag = #{delFlag}, update_by = #{updateBy}, update_time = sysdate(), remark = #{remark},
