mapper.select:
select r.sale_id, r.dept_id, r.period_id, r.sale_no, r.product_id, r.member_id, r.member_no, r.member_name, r.product_name, r.sale_quantity, r.gift_quantity, r.total_quantity, r.sale_amount, r.unit_price, r.paid_amount, r.sale_date, r.status, r.del_flag, r.create_by, r.create_time, r.update_by, r.update_time, r.remark, p.period_no as period_no, p.status as period_status, (select max(sp.payment_date) from fin_sale_payment sp where sp.sale_id = r.sale_id and sp.del_flag = '0') as latest_payment_date from fin_sale_record r left join fin_accounting_period p on r.period_id = p.period_id
r.del_flag = '0' and coalesce(r.paid_amount, 0) < r.sale_amount and r.dept_id = #{deptId} and r.period_id = #{periodId} and r.sale_no like concat('%', #{saleNo}, '%') and r.product_name like concat('%', #{productName}, '%') and r.status = #{status}
order by r.sale_date asc, r.sale_id asc

select count(*)
from fin_sale_record r
where r.del_flag = '0'
  and coalesce(r.paid_amount, 0) < r.sale_amount
   and r.dept_id = #{deptId}
   and r.period_id = #{periodId}

select coalesce(sum(r.sale_amount - coalesce(r.paid_amount, 0)), 0)
from fin_sale_record r
where r.del_flag = '0'
  and coalesce(r.paid_amount, 0) < r.sale_amount
   and r.dept_id = #{deptId}
   and r.period_id = #{periodId}

select date_format(r.sale_date, '%Y-%m-%d') as dateStr, r.dept_id as deptId, d.dept_name as deptName, ifnull(sum(r.sale_amount), 0) as totalSales from fin_sale_record r left join sys_dept d on r.dept_id = d.dept_id r.del_flag = '0'
and r.dept_id in
#{deptId}
and r.sale_date >= #{startTime}
and r.sale_date <= #{endTime}
group by date_format(r.sale_date, '%Y-%m-%d'), r.dept_id, d.dept_name order by dateStr, r.dept_id

