select ifnull(sum(sale_amount), 0) from fin_sale_record
where del_flag = '0' and date(sale_date) = curdate()

    and dept_id in #{deptId}

select ifnull(sum(sale_amount), 0) from fin_sale_record
where del_flag = '0' and date_format(sale_date, '%Y-%m') = date_format(curdate(), '%Y-%m')

    and dept_id in #{deptId}

select ifnull(sum(sale_amount), 0) from fin_sale_record
where del_flag = '0' and date(sale_date) = date_sub(curdate(), interval 1 day)

    and dept_id in #{deptId}

select ifnull(sum(sale_amount), 0) from fin_sale_record
where del_flag = '0' and date_format(sale_date, '%Y-%m') = date_format(date_sub(curdate(), interval 1 month), '%Y-%m')

    and dept_id in #{deptId}

select r.dept_id as deptId, d.dept_name as deptName, ifnull(sum(r.sale_amount), 0) as totalSales, count(1) as orderCount, ifnull(sum(r.total_quantity), 0) as totalQuantity from fin_sale_record r left join sys_dept d on r.dept_id = d.dept_id r.del_flag = '0'
and r.dept_id in #{deptId}
and r.sale_date >= #{startTime} and r.sale_date <= #{endTime}
group by r.dept_id, d.dept_name order by totalSales desc

select r.product_id as productId, r.product_name as productName, ifnull(sum(r.sale_amount), 0) as totalSales, ifnull(sum(r.total_quantity), 0) as totalQuantity, r.dept_id as deptId, d.dept_name as deptName from fin_sale_record r left join sys_dept d on r.dept_id = d.dept_id r.del_flag = '0'
and r.dept_id in #{deptId}
and r.sale_date >= #{startTime} and r.sale_date <= #{endTime}
group by r.product_id, r.product_name, r.dept_id, d.dept_name order by totalSales desc limit 20

select ifnull(sum(r.sale_amount), 0) from fin_sale_record r
 r.del_flag = '0'
and r.sale_no in (select sr.sale_no from fin_sale_record sr where sr.del_flag = '0' and sr.remark like '%member%')

    and r.dept_id in #{deptId}

 and r.sale_date >= #{startTime} 
 and r.sale_date <= #{endTime}

select ifnull(sum(r.sale_amount), 0) from fin_sale_record r
 r.del_flag = '0' and r.remark like '%seckill%'

    and r.dept_id in #{deptId}

 and r.sale_date >= #{startTime} 
 and r.sale_date <= #{endTime}

select coalesce(sum(sp.payment_amount), 0)
from fin_sale_payment sp
where sp.del_flag = '0'
and sp.period_id = #{periodId}

    and sp.dept_id in #{deptId}

select coalesce(sum(sp.payment_amount), 0)
from fin_sale_payment sp
inner join fin_sale_record sr on sr.sale_id = sp.sale_id
where sp.del_flag = '0' and sr.del_flag = '0'

    and sp.period_id = #{periodId}
    and sr.period_id != #{periodId}


    and sp.dept_id in #{deptId}

select coalesce(sum(r.sale_amount - coalesce(r.paid_amount, 0)), 0)
from fin_sale_record r
where r.del_flag = '0'
and coalesce(r.paid_amount, 0) < r.sale_amount
and r.period_id = #{periodId}

    and r.dept_id in #{deptId}
